def solve(intervals):
    # Filter out malformed intervals (e.g., empty sublists)
    valid = [iv for iv in intervals if isinstance(iv, (list, tuple)) and len(iv) == 2]
    if not valid:
        return []
    # Ensure each interval is a list to allow modification
    intervals = [list(iv) for iv in valid]
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0][:]]
    for start, end in intervals[1:]:
        last = merged[-1]
        if start <= last[1]:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

