    """Return length of longest strictly increasing subsequence.
    Uses patience sorting (binary search) in O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest tail of an increasing subseq of length i+1
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
