def solve(grid):
    """Count the number of islands (connected components of 1s) in a possibly jagged grid.
    Cells are connected 4-directionally. The function is robust to empty grids,
    empty rows, and rows of differing lengths.
    """
    if not isinstance(grid, list) or not grid:
        return 0
    rows = len(grid)
    visited = set()
    def get_val(r, c):
        # Return cell value if within bounds, else None
        if 0 <= r < rows:
            row = grid[r]
            if isinstance(row, list) and 0 <= c < len(row):
                return row[c]
        return None
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if get_val(nx, ny) == 1 and (nx, ny) not in visited:
                    stack.append((nx, ny))
    count = 0
    for i in range(rows):
        row = grid[i]
        if not isinstance(row, list):
            continue
        for j in range(len(row)):
            if row[j] == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

